-- Passage rg6-main-idea-summary-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('3079d50c-92ae-53ec-8cf2-a5d6b8c5bb75', 'rg6-main-idea-summary-p03', (select id from public.skills where slug = 'read-g6-main-idea-summary'), null,
        '6-8', $q$A New Life for Old Paper$q$, $q$When you drop a sheet of paper in a recycling bin, its story is not over. Recycled paper goes through several steps that turn it back into material for new products. Each step removes something unwanted or rebuilds the paper's fibers.

Paper is made of tiny plant fibers, mostly from wood. At a recycling center, workers and machines first sort paper by type. Newspapers, cardboard and office paper are kept apart because their fibers differ in length and strength.

Next, the sorted paper goes into a huge tank called a pulper. Water and machinery churn the paper until it breaks apart into a soupy mix of fibers called pulp. Screens then remove staples, tape and bits of plastic.

The pulp still contains ink. To lift it out, the mill adds soapy chemicals and blows air through the mixture. The ink sticks to the air bubbles, which rise to the top as foam that can be skimmed away. Cleaner pulp is left behind.

Finally, the pulp is sprayed onto a moving screen. Water drains away, and heated rollers press and dry the fibers into a long sheet. That sheet is rolled up and later cut into products such as cereal boxes, tissues and notebook paper.

Paper cannot be recycled forever. Each trip through the process makes the fibers shorter and weaker. After about five to seven rounds, they are too short to hold together. Even so, recycling paper several times saves trees, water and energy compared with making paper from new wood.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
