  ('27cb7bb8-001d-56d7-b0f8-4243aeb0f785', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'easy',
   $q$Which statement best expresses a theme of the passage?$q$, $q$[{"text":"Trolleys were a better way to travel than the buses people ride today.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Students should always choose history projects about transportation.","is_correct":false,"misconception_token":"too-narrow"},{"text":"Riding a bike is the best way to explore a town and its streets.","is_correct":false,"misconception_token":"topic-not-theme"},{"text":"Learning about the past can change the way you see familiar places.","is_correct":true}]$q$::jsonb, $q$Learning about the past can change the way you see familiar places.$q$, $q$Mateo begins by never noticing the ground and ends by seeing every street as "a story that is still going." The story never compares trolleys and buses as better or worse, so that choice is not supported.$q$, 'draft', '14fcc73f-3c0a-5788-a24e-329e490e74c3')
