  ('3125eb93-cdb0-524d-aa74-2dcb5406276e', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'easy',
   $q$Which choice is the best objective summary of the poem?$q$, $q$[{"text":"A student who is very talented makes cups that are much better than they think.","is_correct":false,"misconception_token":"includes-opinion"},{"text":"A student's brother learns to skate after falling a hundred times on the ice.","is_correct":false,"misconception_token":"too-narrow"},{"text":"A student makes beautiful pottery on the first try and sells the cups in spring.","is_correct":false,"misconception_token":"adds-false-detail"},{"text":"A student keeps failing at the pottery wheel, practices with a teacher's support, and by spring has made seven imperfect cups.","is_correct":true}]$q$::jsonb, $q$A student keeps failing at the pottery wheel, practices with a teacher's support, and by spring has made seven imperfect cups.$q$, $q$The correct summary covers the failures, the practice and the finished cups. The brother's skating is only one comparison in the third stanza, not the whole poem.$q$, 'draft', '179ba9a1-e7d8-5901-ae6b-a2ff5d8f8340')
