  ('80952e07-ea00-509f-995d-57094bc1a544', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'medium',
   $q$How does the third stanza, about the speaker's brother, help develop the theme?$q$, $q$[{"text":"It gives another example of someone who falls many times before succeeding.","is_correct":true},{"text":"It shows that the brother is better at learning new skills than the speaker.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It changes the subject from pottery to a sport the speaker likes better.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"It explains why the speaker's first bowl slumped like a tired hat.","is_correct":false,"misconception_token":"confuses-cause-effect"}]$q$::jsonb, $q$It gives another example of someone who falls many times before succeeding.$q$, $q$The brother falls "a hundred times to stand," which matches the speaker's own failures at the wheel. The poem never compares who learns faster, so that choice is not supported.$q$, 'draft', '179ba9a1-e7d8-5901-ae6b-a2ff5d8f8340')
