  ('1b8d9d4a-d8ae-5fe3-9ebd-e12463e77fc8', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'medium',
   $q$What does Ms. Okonkwo mean when she says the wheel "never counts the times you fail"?$q$, $q$[{"text":"Students should hide their failures so the teacher does not see them.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The pottery wheel is broken and cannot keep track of the bowls.","is_correct":false,"misconception_token":"literal-reading"},{"text":"Each new try is a fresh start, so past mistakes should not stop you.","is_correct":true},{"text":"Failing at pottery does not matter because pottery is not important.","is_correct":false,"misconception_token":"overgeneralizes"}]$q$::jsonb, $q$Each new try is a fresh start, so past mistakes should not stop you.$q$, $q$She scrapes the clay back to be used again, showing that a failed bowl simply becomes the next chance. Reading the line as a fact about a broken machine misses its meaning.$q$, 'draft', '179ba9a1-e7d8-5901-ae6b-a2ff5d8f8340')
