  ('20125ab7-1cd7-5ea1-a85c-32f92e7011f7', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'hard',
   $q$Why does the speaker choose to drink cocoa from "the worst" cup?$q$, $q$[{"text":"The flawed cup is a reminder of the effort and failures that led to success.","is_correct":true},{"text":"The speaker plans to throw the worst cup away once it is used up.","is_correct":false,"misconception_token":"misreads-ending"},{"text":"The speaker wants to hide the worst cup so no visitors will see it.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The worst cup is the largest one, so it holds the most cocoa.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$The flawed cup is a reminder of the effort and failures that led to success.$q$, $q$The last stanza says the cup "holds the story of my hands, / and every time I sat and tried," so its flaws are what make it special. The poem never says the cup is large, so that choice adds an unsupported reason.$q$, 'draft', '179ba9a1-e7d8-5901-ae6b-a2ff5d8f8340')
