  ('9645a631-14fd-5e8b-8b67-272d28ecd9a4', null, (select id from public.skills where slug = 'read-g6-theme-summary'), null, 'easy',
   $q$Which statement best expresses the theme of the fable?$q$, $q$[{"text":"The moon is the most important light in the whole meadow.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Beetles should never wander away from their homes at night.","is_correct":false,"misconception_token":"too-narrow"},{"text":"Do not wait for someone more powerful when you can help right now.","is_correct":true},{"text":"Fireflies are the most helpful insects that live in a meadow.","is_correct":false,"misconception_token":"topic-not-theme"}]$q$::jsonb, $q$Do not wait for someone more powerful when you can help right now.$q$, $q$Pip's tiny light saves the beetle while the moon never helps at all. The beetle wandering off starts the problem, but the lesson is about Pip choosing to act instead of waiting.$q$, 'draft', '825b3092-fb82-5c21-bd93-b8164252b46a')
