-- Passage rg7-character-setting-plot-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('4b8624ce-4220-588f-a840-c59d8eaca327', 'rg7-character-setting-plot-p06', (select id from public.skills where slug = 'read-g7-character-setting-plot'), null,
        '6-8', $q$Apartment 4C$q$, $q$The walls in our building are thin as paper,
so I practice violin with the window shut
and the mute clipped on, the notes coming out
small and gray, like a voice behind a door.

For a month I play my scales for no one.
Then one evening, through the wall,
someone knocks: two taps, a pause, two taps,
in time with the song I am learning.

I stop. The knocking stops.
I play again, and it comes back,
patient and steady as a clock,
keeping the beat I keep losing.

Mom says it is Mrs. Abernathy in 4D,
who taught music before I was born
and does not leave her apartment much now.
I had only seen her name on a mailbox.

So I take the mute off.
I open the window to the courtyard
and play the whole song, wrong notes and all,
loud enough for the wall to hear.

On Saturday I knock on her door
with my violin case and a plate of rice cakes.
She opens it before my second knock,
already humming the first line.$q$, 'draft')
